WITH RankedPosts AS (SELECT P.Id AS PostId, P.Title, P.CreationDate, P.Score, P.ViewCount, U.DisplayName AS OwnerName, RANK() OVER (PARTITION BY P.OwnerUserId ORDER BY P.Score DESC NULLS FIRST) AS PostRank FROM Posts AS P JOIN Users AS U ON P.OwnerUserId = U.Id WHERE P.CreationDate >= CURRENT_DATE() - INTERVAL '1' YEAR), PostVoteSummary AS (SELECT PostId, SUM(CASE WHEN VoteTypeId = 2 THEN 1 ELSE 0 END) AS UpVotes, SUM(CASE WHEN VoteTypeId = 3 THEN 1 ELSE 0 END) AS DownVotes, COUNT(*) AS TotalVotes FROM Votes GROUP BY PostId), CloseReasonSummary AS (SELECT PH.PostId, COUNT(PH.Id) AS CloseReasonCount, GROUP_CONCAT(CR.Name, ', ') AS CloseReasons FROM PostHistory AS PH JOIN CloseReasonTypes AS CR ON CAST(PH.Comment AS Nullable(Int32)) = CR.Id WHERE PH.PostHistoryTypeId IN (10, 11) GROUP BY PH.PostId) SELECT RP.PostId, RP.Title, RP.CreationDate, RP.Score, RP.ViewCount, RP.OwnerName, COALESCE(PVS.UpVotes, 0) AS UpVotes, COALESCE(PVS.DownVotes, 0) AS DownVotes, COALESCE(PVS.TotalVotes, 0) AS TotalVotes, COALESCE(CRS.CloseReasonCount, 0) AS CloseReasonCount, COALESCE(CRS.CloseReasons, 'No close reasons') AS CloseReasons, CASE WHEN RP.PostRank = 1 THEN 'Top Post' WHEN RP.PostRank <= 5 THEN 'High Performer' ELSE 'Regular Post' END AS PerformanceCategory FROM RankedPosts AS RP LEFT JOIN PostVoteSummary AS PVS ON RP.PostId = PVS.PostId LEFT JOIN CloseReasonSummary AS CRS ON RP.PostId = CRS.PostId WHERE RP.PostRank <= 10 ORDER BY RP.Score DESC NULLS FIRST, RP.ViewCount DESC NULLS FIRST